import { FilterItem } from '@/types'
import { Block } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CoinInfo } from '@cetus/types'
import { Icon, RefreshButton, SingleCoinImage } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Flex, HStack, Switch, Text } from '@chakra-ui/react'
import { useState } from 'react'
import TokenSelectModal from '../tokenSelectModal'
import IncentiveTypesBlock from './IncentiveTypesBlock'
interface FilterProps {
  isDisplayChecked: boolean
  handleIsDisplayChecked: () => void
  currentCheckedArr: string[]
  onClickIncentiveTypes: (item: FilterItem) => void
  handleRefresh: () => void
  selectCoinList: CoinInfo[]
  onClickSelectCoinList: (tokenInfo: CoinInfo) => void
  onDeleteSelectCoinList: (tokenInfo: CoinInfo) => void
}

function PoolsFilter({
  isDisplayChecked,
  handleIsDisplayChecked,
  currentCheckedArr,
  onClickIncentiveTypes,
  handleRefresh,
  selectCoinList,
  onClickSelectCoinList,
  onDeleteSelectCoinList
}: FilterProps) {
  const [isOpenModal, setIsOpenModal] = useState(false)
  const { isApp } = useWindowWidth()
  return (
    <HStack
      w="100%"
      justify="space-between"
      flexDirection={{
        base: 'column',
        lg: 'row'
      }}
    >
      <HStack
        w={{
          base: '100%',
          lg: 'unset'
        }}
      >
        <Block
          cursor="pointer"
          h="40px"
          borderRadius="12px"
          minW={{
            base: 'calc(100% - 48px)',
            lg: '230px'
          }}
          w="unset"
          p="0px 4px 0 10px"
          onClick={() => (selectCoinList.length >= 2 ? '' : setIsOpenModal(true))}
        >
          <HStack h="100%" align="center">
            <Flex align="center" h="100%">
              <Icon xlinkHref="#icon-icon_search" svgHover="text_paragraph" />
              <Text ml="4px">Filter by token</Text>
            </Flex>
            {selectCoinList?.map((item: CoinInfo) => {
              return (
                <HStack
                  gap="4px"
                  align="center"
                  bg="button_ghost_bg"
                  borderRadius="8px"
                  p="5px 8px"
                  key={item?.coin_type}
                  onClick={(e: any) => cancelBubble(e)}
                >
                  <SingleCoinImage imageUrl={item?.logo_url} w="20px" h="20px" />
                  <Text ml="2px" color="text_caption" lineHeight="1">
                    {item?.symbol}
                  </Text>
                  <Icon xlinkHref="#icon-icon_close" onClick={() => onDeleteSelectCoinList(item)} />
                </HStack>
              )
            })}
          </HStack>
        </Block>
        {isApp && <RefreshButton handleRefresh={handleRefresh} />}
      </HStack>
      <HStack
        w={{
          base: '100%',
          lg: 'unset'
        }}
        justify="space-between"
        gap="8px"
      >
        <HStack
          w={{
            base: '50%',
            lg: 'unset'
          }}
          p="12px 10px"
          bg="bg_secondary"
          borderRadius="12px"
          h="40px"
          align="center"
          border="1px solid"
          borderColor="border"
          onClick={handleIsDisplayChecked}
          justify="space-between"
        >
          {!isApp && <Icon xlinkHref="#icon-icon_type" svgHover="text_paragraph" />}
          <Text color={isDisplayChecked ? 'text_caption' : 'text_paragraph'}>Display all pools</Text>
          <Switch isChecked={isDisplayChecked} onChange={handleIsDisplayChecked} />
        </HStack>
        <IncentiveTypesBlock currentCheckedArr={currentCheckedArr} onClickIncentiveTypes={onClickIncentiveTypes} />
        {!isApp && <RefreshButton handleRefresh={handleRefresh} />}
      </HStack>
      <TokenSelectModal
        isOpen={isOpenModal}
        onSelectToken={(tokenInfo: CoinInfo) => {
          onClickSelectCoinList(tokenInfo)
        }}
        onClose={() => {
          setIsOpenModal(false)
        }}
      />
    </HStack>
  )
}

export default PoolsFilter
