import PoolsFilter from '@/components/pools/PoolsFilter'
import useGetPoolList from '@/hooks/pool/useGetPoolList'
import usePoolsStore from '@/store/pool'
import { FilterItem } from '@/types'
import { SortDropBlock, TableSortTh } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CoinInfo } from '@cetus/types'
import { NoData, Spinner, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { Box, Button, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import AprTooltip from '../common/AprTooltip'
import CoinPairInfo from '../common/CoinPairInfo'
import FarmingIcon from '../common/FarmingIcon'
import MiningIcon from '../common/MiningIcon'
import VaultsIcon from '../common/VaultsIcon'
import ActionsBlock from './ActionsBlock'
import RewardsBlock from './RewardsBlock'

type sortRule = 'desc' | 'asc'
export type poolListType = {
  label: 'Liquidity' | 'Volume (24H)' | 'Volume (7D)' | 'Fees (24H)' | 'APR (24H)'
  value: 'tvl' | 'vol' | 'vol7d' | 'fees24h' | 'totalApr'
}
function PoolsContent() {
  const { setPoolListLength } = usePoolsStore()
  const { getPoolList } = useGetPoolList()
  const [currentCheckedArr, setCurrentCheckedArr] = useState<string[]>(['mining', 'farming', 'noIncentives'])
  const onClickIncentiveTypes = (item: FilterItem) => {
    console.log('🚀 ~ onClickIncentiveTypes ~ item:', item)
    setCurrentCheckedArr(prev => (prev.includes(item.value) ? prev.filter(val => val !== item.value) : [...prev, item.value]))
  }

  const [isDisplayChecked, setIsDisplayChecked] = useState(false)
  const handleIsDisplayChecked = () => {
    setCurrentPage(1)
    fetchPoolsData({ offset: 0, display_all_pools: !isDisplayChecked })
    setIsDisplayChecked(prev => {
      console.log('🚀 ~ handleIsDisplayChecked ~ prev:', prev)
      return !prev
    })
  }
  const handleRefresh = () => {
    console.log('🚀 ~ handleRefresh ~ handleRefresh:')
    setCurrentPage(1)
    fetchPoolsData({ offset: 0 })
  }

  const [selectCoinList, setSelectCoinList] = useState<CoinInfo[]>([])

  const onClickSelectCoinList = (tokenInfo: CoinInfo) => {
    console.log('🚀 ~ onClickIncentiveTypes ~ tokenInfo:', tokenInfo)
    setSelectCoinList(prev => [...prev, tokenInfo])
  }
  const onDeleteSelectCoinList = (tokenInfo: CoinInfo) => {
    console.log('🚀 ~ onClickIncentiveTypes ~ tokenInfo:', tokenInfo)
    setSelectCoinList(prev => prev.filter(ele => ele?.coin_type !== tokenInfo?.coin_type))
  }

  const pageSize = 20
  const [isLoadMoreLoading, setIsLoadMoreLoading] = useState(true)
  const [isLoading, setIsLoading] = useState(true)
  const [sortRule, setSortRule] = useState<sortRule>('desc')
  const [sortBy, setSortBy] = useState<poolListType>({ label: 'Liquidity', value: 'tvl' })
  const [list, setList] = useState([])
  const [total, setTotal] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  interface fetchPoolsDataParams {
    is_vaults?: boolean
    display_all_pools?: boolean
    has_mining?: boolean
    has_farming?: boolean
    no_incentives?: boolean
    order_by?: string
    limit?: number
    offset?: number
    coin_type?: string
    pool?: string
  }
  const fetchPoolsData = async (params: fetchPoolsDataParams) => {
    console.log('🚀 ~ fetchPoolsData ~ params:', params)
    const coin =
      selectCoinList.length == 2
        ? `${selectCoinList[0]?.coin_type},${selectCoinList[1]?.coin_type}`
        : selectCoinList.length == 1
          ? `${selectCoinList[0]?.coin_type}`
          : ''
    const {
      is_vaults = false,
      display_all_pools = isDisplayChecked,
      has_mining = currentCheckedArr.includes('mining'),
      has_farming = currentCheckedArr.includes('farming'),
      no_incentives = currentCheckedArr.includes('noIncentives'),
      order_by = sortRule == 'desc' ? `-${sortBy?.value}` : `${sortBy?.value}`,
      limit = pageSize,
      offset = 0,
      coin_type = coin,
      pool = ''
    } = params
    if (Number(offset) >= pageSize) {
      setIsLoadMoreLoading(true)
    } else {
      setIsLoading(true)
    }
    const query = { is_vaults, display_all_pools, has_mining, has_farming, no_incentives, order_by, limit, offset, coin_type, pool }
    const result: any = await getPoolList(query)
    if (result) {
      console.log('🚀 ~ fetchDatafetchPoolsData ~ result:', result)
      if (Number(offset) >= pageSize) {
        setList(prev => prev.concat(result.list))
      } else {
        setList(result.list)
      }
      setTotal(result.total)
      setPoolListLength(result.total)
      setIsLoading(false)
      setIsLoadMoreLoading(false)
    }
  }

  useEffect(() => {
    console.log('🚀 ~ PoolsContent ~ selectCoinList:', selectCoinList)
    setCurrentPage(1)
    fetchPoolsData({ offset: 0 })
  }, [currentCheckedArr, selectCoinList])

  const clickSort = (item: poolListType) => {
    setCurrentPage(1)
    console.log('🚀 ~ clickSort ~ item:', item)
    if (item?.value == sortBy?.value) {
      fetchPoolsData({ offset: 0, order_by: sortRule == 'desc' ? `-${item?.value}` : `${item?.value}` })
      const rule = sortRule == 'desc' ? 'asc' : 'desc'
      setSortRule(rule)
    } else {
      fetchPoolsData({ offset: 0, order_by: `-${item?.value}` })
      setSortRule('desc')
      setSortBy(item)
    }
  }

  const sortByList = [
    { label: 'Liquidity', value: 'tvl' },
    { label: 'Volume (24H)', value: 'vol' },
    { label: 'Fees (24H)', value: 'fees24h' },
    { label: 'APR', value: 'totalApr' }
  ]
  const sortByObject = sortByList.reduce((obj: any, item) => {
    obj[item.value] = item
    return obj
  }, {})

  const changeCurrentPage = () => {
    const pageOffset = currentPage * pageSize
    fetchPoolsData({ offset: pageOffset })
    setCurrentPage(prev => prev + 1)
  }

  const { isApp } = useWindowWidth()

  const navigate = useNavigate()

  const hasLoadMore = useMemo(() => {
    const currentSize = (currentPage - 1) * pageSize + list?.length
    return Number(total) > currentSize
  }, [total, currentPage, pageSize])

  return (
    <VStack gap="20px" w="100%" background="bg_primary">
      <PoolsFilter
        isDisplayChecked={isDisplayChecked}
        handleIsDisplayChecked={handleIsDisplayChecked}
        currentCheckedArr={currentCheckedArr}
        onClickIncentiveTypes={onClickIncentiveTypes}
        handleRefresh={handleRefresh}
        selectCoinList={selectCoinList}
        onClickSelectCoinList={onClickSelectCoinList}
        onDeleteSelectCoinList={onDeleteSelectCoinList}
      />
      <Box h="1px" w="100%" bg="border" />
      <VStack w="100%" position="relative" gap="20px">
        {!isLoading && list?.length == 0 ? (
          <NoData type="nodata" />
        ) : isApp ? (
          <VStack w="100%">
            <HStack w="100%" justify="space-between">
              <Text fontSize="24px" color="text_caption">
                Pools
              </Text>
              <SortDropBlock sortText="Sort" minW="205px" currentSort={sortBy} sortByList={sortByList} onSortByChange={clickSort} />
            </HStack>
            <H5MapTable
              rowKey="poolAddress"
              dataSource={list}
              columns={getColumns(sortRule, sortBy, clickSort, sortByObject)}
              loading={isLoading}
              itemSkeletonLength={7}
              itemHeight="30px"
              rowStyle={(_, index) => ({
                w: '100%',
                p: '0px',
                mt: '12px'
              })}
              onRowClick={item => {
                navigate('/pools')
              }}
              x
            />
          </VStack>
        ) : (
          <Table
            rowKey="poolAddress"
            columns={getColumns(sortRule, sortBy, clickSort, sortByObject)}
            dataSource={list}
            skeletonLength={10}
            loading={isLoading}
            onRowClick={item => {
              // TODO
              navigate('/pools')
            }}
            rowStyle={{ h: '80px', cursor: 'pointer' }}
          />
        )}
        {!isLoading && hasLoadMore && (
          <Button
            w="172px"
            h="32px"
            fontSize="12px"
            borderRadius="8px"
            bg="button_ghost_bg"
            color="primary"
            borderColor="border"
            variant="outline"
            onClick={changeCurrentPage}
          >
            {isLoadMoreLoading ? <Spinner /> : 'Load More'}
          </Button>
        )}
      </VStack>
    </VStack>
  )
}

const getColumns = (sortRule: string, sortBy: poolListType, clickSort: (value: poolListType) => void, sortByObject: any) => {
  return [
    {
      title: <Text fontSize="14px">Pools</Text>,
      key: 'pool',
      thConfig: {
        w: '30%'
      },
      showLabel: false,
      render: (item: any) => {
        return (
          <HStack>
            <CoinPairInfo poolInfo={item} />
            {item?.haveFarming && <FarmingIcon />}
            {item?.haveMining && <MiningIcon />}
            {item?.haveVaults && <VaultsIcon />}
          </HStack>
        )
      }
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['tvl']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'tvlDisplay'
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['vol']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'volume24Display'
    },
    {
      title: <Text>Mining Rewards</Text>,
      key: 'rewards',
      render: ({ miningRewardList }: { miningRewardList: any }) => {
        return <RewardsBlock miningRewardList={miningRewardList} />
      }
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['fees24h']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'fees24Display'
    },
    {
      title: (
        <TableSortTh
          labelInfo={sortByObject['totalApr']}
          sortRule={sortRule}
          sortBy={sortBy}
          tooltip={{ type: 'apr24' }}
          clickSort={(value: poolListType) => clickSort(value)}
          justifyContent="flex-end"
        />
      ),
      key: 'apr24h',
      thConfig: {
        w: '8%'
      },
      render: (item: any) => {
        return <AprTooltip poolInfo={item} />
      }
    },
    {
      title: <Text>Actions</Text>,
      showLabel: false,
      key: 'actions',
      render: (item: any) => {
        return <ActionsBlock />
      }
    }
  ]
}
export default PoolsContent
